UPDATE sys_scheduler_job
   SET lock_until = NOW() + make_interval(secs => #{leaseSeconds})
 WHERE job_code   = #{jobCode}
   AND lock_owner = #{owner}

UPDATE sys_scheduler_job
   SET lock_owner = NULL
      ,locked_at  = NULL
      ,lock_until = NULL
 WHERE job_code = #{jobCode}
   AND lock_owner = #{owner}

