INSERT INTO sys_scheduler_history (
    job_code, trigger_type, status, scheduled_at, started_at, finished_at,
    duration_ms, processed_count, message, error_message, instance_id
) VALUES (
    #{jobCode}, #{triggerType}, #{status}, #{scheduledAt}, #{startedAt}, #{finishedAt},
    #{durationMs}, #{processedCount}, #{message}, #{errorMessage}, #{instanceId}
)

mapper.update:
UPDATE sys_scheduler_history
   SET status          = #{status}
      ,finished_at     = #{finishedAt}
      ,duration_ms     = #{durationMs}
      ,processed_count = #{processedCount}
      ,message         = #{message}
      ,error_message   = #{errorMessage}
 WHERE history_id = #{historyId}

UPDATE sys_scheduler_job
   SET last_started_at = #{startedAt}
      ,last_status     = 'RUNNING'
 WHERE job_code = #{jobCode}

UPDATE sys_scheduler_job
   SET last_finished_at = #{finishedAt}
      ,last_status      = #{status}
      ,last_message     = #{message}

      ,last_success_at  = #{finishedAt}

 WHERE job_code = #{jobCode}
